def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'D'
    my_last, opp_last = history[-1]
    opp_prev = [o for m, o in history]
    my_prev = [m for m, o in history]
    opp_c = opp_prev.count('C')
    opp_d = n - opp_c
    if n == 1:
        if opp_last == 'D':
            return 'D'
        return 'C'
    if n >= 96:
        return 'D'
    if n >= 90:
        if opp_d >= 2:
            return 'D'
        return 'C'
    if my_last == 'C':
        if opp_last == 'C':
            if n >= 3:
                if opp_prev[-3] == 'D':
                    return 'D'
            return 'C'
        else:
            if n >= 5 and opp_c > opp_d:
                return 'C'
            return 'D'
    else:
        if opp_last == 'C':
            if n >= 3 and opp_prev[-2:] == ['C', 'C']:
                return 'C'
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        else:
            if opp_d >= n * 2 // 3:
                return 'D'
            if n >= 4 and opp_prev[-4:] == ['D', 'D', 'D', 'D']:
                return 'D'
            if rng.random() < 0.2:
                return 'C'
            return 'D'
